WITH cleaned AS (SELECT *, CAST(amount AS INT) AS amount_int, COALESCE(method, 'DIRECT') AS resolved_method FROM payments WHERE method IS NOT NULL AND method IS DISTINCT FROM 'promptpay') SELECT id, method, paid_at, amount_int, MAX(amount_int) OVER w_ordered AS last7_max_amount_int, AVG(amount_int) OVER w_ordered AS last7_avg_amount_int, MIN(amount_int) OVER w_ordered AS last7_min_amount_int, COUNT(amount_int) OVER (PARTITION BY YEAR(paid_at), method) AS paid_at_year_count_amount_int FROM cleaned WHERE status NOT IN ('REFUNDED', 'SUCCESS') WINDOW w_ordered AS (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
